const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

// In-memory storage for events and aggregated data
let events = [];
let aggregatedData = {
  topProducts: {},
  conversionFunnel: {},
  hourlyActivity: {}
};

// Product Event interface matching our Moose model
class ProductEvent {
  constructor(data) {
    this.event_id = data.event_id;
    this.event_ts = new Date(data.event_ts);
    this.user_id = data.user_id;
    this.product_id = data.product_id;
    this.event_type = data.event_type;
    this.properties = data.properties || {};
  }
}

// Helper function to update aggregated data
function updateAggregations(event) {
  // Update top products
  if (!aggregatedData.topProducts[event.product_id]) {
    aggregatedData.topProducts[event.product_id] = {
      product_id: event.product_id,
      views: 0,
      purchases: 0,
      revenue: 0
    };
  }

  const product = aggregatedData.topProducts[event.product_id];
  if (event.event_type === 'view') {
    product.views++;
  } else if (event.event_type === 'purchase') {
    product.purchases++;
    product.revenue += event.properties.price || 0;
  }

  // Update conversion funnel (user journey)
  const userId = event.user_id;
  if (!aggregatedData.conversionFunnel[userId]) {
    aggregatedData.conversionFunnel[userId] = {
      user_id: userId,
      views: 0,
      purchases: 0,
      first_view: null,
      first_purchase: null
    };
  }

  const userFunnel = aggregatedData.conversionFunnel[userId];
  if (event.event_type === 'view') {
    userFunnel.views++;
    if (!userFunnel.first_view) {
      userFunnel.first_view = event.event_ts;
    }
  } else if (event.event_type === 'purchase') {
    userFunnel.purchases++;
    if (!userFunnel.first_purchase) {
      userFunnel.first_purchase = event.event_ts;
    }
  }

  // Update hourly activity
  const hour = event.event_ts.toISOString().substr(0, 13) + ':00:00.000Z';
  if (!aggregatedData.hourlyActivity[hour]) {
    aggregatedData.hourlyActivity[hour] = {
      hour: hour,
      total_events: 0,
      views: 0,
      purchases: 0,
      unique_users: new Set()
    };
  }

  const hourlyData = aggregatedData.hourlyActivity[hour];
  hourlyData.total_events++;
  hourlyData.unique_users.add(event.user_id);
  if (event.event_type === 'view') {
    hourlyData.views++;
  } else if (event.event_type === 'purchase') {
    hourlyData.purchases++;
  }
}

// POST /ingest - Event ingestion endpoint
app.post('/ingest', (req, res) => {
  const startTime = Date.now();

  try {
    const eventData = req.body;
    const event = new ProductEvent(eventData);

    // Store the event
    events.push(event);

    // Update aggregations in real-time
    updateAggregations(event);

    const responseTime = Date.now() - startTime;
    res.status(200).json({
      success: true,
      event_id: event.event_id,
      processing_time_ms: responseTime
    });
  } catch (error) {
    const responseTime = Date.now() - startTime;
    res.status(400).json({
      success: false,
      error: error.message,
      processing_time_ms: responseTime
    });
  }
});

// GET /analytics/top-products - Top products by views and purchases
app.get('/analytics/top-products', (req, res) => {
  const startTime = Date.now();

  const limit = parseInt(req.query.limit) || 10;

  const topProducts = Object.values(aggregatedData.topProducts)
    .sort((a, b) => (b.views + b.purchases) - (a.views + a.purchases))
    .slice(0, limit)
    .map(product => ({
      product_id: product.product_id,
      total_interactions: product.views + product.purchases,
      views: product.views,
      purchases: product.purchases,
      revenue: product.revenue,
      conversion_rate: product.views > 0 ? (product.purchases / product.views * 100).toFixed(2) : 0
    }));

  const responseTime = Date.now() - startTime;
  res.status(200).json({
    data: topProducts,
    total_products: topProducts.length,
    processing_time_ms: responseTime
  });
});

// GET /analytics/conversion-funnel - Conversion funnel analysis
app.get('/analytics/conversion-funnel', (req, res) => {
  const startTime = Date.now();

  const funnelData = Object.values(aggregatedData.conversionFunnel);
  const totalUsers = funnelData.length;
  const usersWithViews = funnelData.filter(u => u.views > 0).length;
  const usersWithPurchases = funnelData.filter(u => u.purchases > 0).length;

  const funnel = {
    total_users: totalUsers,
    users_with_views: usersWithViews,
    users_with_purchases: usersWithPurchases,
    view_rate: totalUsers > 0 ? (usersWithViews / totalUsers * 100).toFixed(2) : 0,
    conversion_rate: usersWithViews > 0 ? (usersWithPurchases / usersWithViews * 100).toFixed(2) : 0,
    stages: [
      {
        stage: 'total_users',
        users: totalUsers,
        percentage: 100
      },
      {
        stage: 'viewers',
        users: usersWithViews,
        percentage: totalUsers > 0 ? (usersWithViews / totalUsers * 100).toFixed(2) : 0
      },
      {
        stage: 'purchasers',
        users: usersWithPurchases,
        percentage: totalUsers > 0 ? (usersWithPurchases / totalUsers * 100).toFixed(2) : 0
      }
    ]
  };

  const responseTime = Date.now() - startTime;
  res.status(200).json({
    data: funnel,
    processing_time_ms: responseTime
  });
});

// GET /analytics/hourly-activity - Hourly activity breakdown
app.get('/analytics/hourly-activity', (req, res) => {
  const startTime = Date.now();

  const hours = parseInt(req.query.hours) || 24;

  const hourlyActivity = Object.values(aggregatedData.hourlyActivity)
    .map(hour => ({
      hour: hour.hour,
      total_events: hour.total_events,
      views: hour.views,
      purchases: hour.purchases,
      unique_users: hour.unique_users.size
    }))
    .sort((a, b) => new Date(a.hour) - new Date(b.hour))
    .slice(-hours);

  const responseTime = Date.now() - startTime;
  res.status(200).json({
    data: hourlyActivity,
    total_hours: hourlyActivity.length,
    processing_time_ms: responseTime
  });
});

// GET /health - Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'healthy',
    events_stored: events.length,
    uptime: process.uptime(),
    timestamp: new Date().toISOString()
  });
});

// Start server
const PORT = process.env.PORT || 4000;
app.listen(PORT, () => {
  console.log(`Analytics server running on port ${PORT}`);
  console.log(`Available endpoints:`);
  console.log(`  POST /ingest - Event ingestion`);
  console.log(`  GET /analytics/top-products - Top products`);
  console.log(`  GET /analytics/conversion-funnel - Conversion funnel`);
  console.log(`  GET /analytics/hourly-activity - Hourly activity`);
  console.log(`  GET /health - Health check`);
});

module.exports = app;

