const fs = require('fs');
const path = require('path');

async function loadSeedData() {
  const eventsDir = '/data/events';
  const ingestUrl = 'http://localhost:4000/ingest/ProductEvent';

  console.log('Loading seed data...');

  // Get all event files
  const files = fs.readdirSync(eventsDir).filter(f => f.endsWith('.json')).sort();

  let successCount = 0;
  let errorCount = 0;

  for (const file of files) {
    try {
      const filePath = path.join(eventsDir, file);
      const eventData = JSON.parse(fs.readFileSync(filePath, 'utf8'));

      console.log(`Loading ${file}: ${eventData.event_id}`);

      const response = await fetch(ingestUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(eventData)
      });

      if (response.ok) {
        successCount++;
        console.log(`✅ ${file} loaded successfully`);
      } else {
        const errorText = await response.text();
        console.log(`❌ ${file} failed: ${errorText}`);
        errorCount++;
      }

      // Small delay between requests
      await new Promise(resolve => setTimeout(resolve, 100));

    } catch (error) {
      console.log(`❌ ${file} error: ${error.message}`);
      errorCount++;
    }
  }

  console.log(`\nSeed data loading complete:`);
  console.log(`✅ Success: ${successCount} events`);
  console.log(`❌ Errors: ${errorCount} events`);

  return { successCount, errorCount };
}

// Run if called directly
if (require.main === module) {
  loadSeedData().catch(console.error);
}

module.exports = { loadSeedData };

