import { QueryApi } from "@514labs/moose-lib";

export interface TopProductsParams {
  limit?: number;
}

export interface TopProductsResponse {
  product_id: string;
  total_interactions: number;
  views: number;
  purchases: number;
  revenue: number;
  conversion_rate: number;
}

export default async function topProducts(
  { limit = 10 }: TopProductsParams,
): Promise<TopProductsResponse[]> {
  const query = `
    SELECT
      product_id,
      countIf(event_type = 'view') as views,
      countIf(event_type = 'purchase') as purchases,
      views + purchases as total_interactions,
      sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') as revenue,
      round(purchases / nullIf(views, 0) * 100, 2) as conversion_rate
    FROM currentDatabase().local_ProductEvent
    GROUP BY product_id
    ORDER BY total_interactions DESC
    LIMIT {limit:UInt32}
  `;

  return {
    sql: query,
    parameters: { limit }
  };
}

