import { QueryApi } from "@514labs/moose-lib";

export interface ConversionFunnelParams {}

export interface ConversionFunnelResponse {
  stage: string;
  users: number;
  percentage: number;
}

export default async function conversionFunnel(
  {}: ConversionFunnelParams,
): Promise<ConversionFunnelResponse[]> {
  const query = `
    WITH user_stats AS (
      SELECT
        user_id,
        countIf(event_type = 'view') as views,
        countIf(event_type = 'purchase') as purchases
      FROM currentDatabase().local_ProductEvent
      GROUP BY user_id
    ),
    funnel_data AS (
      SELECT
        count(*) as total_users,
        countIf(views > 0) as users_with_views,
        countIf(purchases > 0) as users_with_purchases
      FROM user_stats
    )
    SELECT
      stage,
      users,
      round(users / funnel_data.total_users * 100, 2) as percentage
    FROM (
      SELECT 'total_users' as stage, total_users as users FROM funnel_data
      UNION ALL
      SELECT 'viewers' as stage, users_with_views as users FROM funnel_data
      UNION ALL
      SELECT 'purchasers' as stage, users_with_purchases as users FROM funnel_data
    ), funnel_data
  `;

  return {
    sql: query,
    parameters: {}
  };
}

