### Get Order Fulfillment Data

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/shared/guides/performant-dashboards/phase-3-query-layer.mdx

Executes a QueryModel against ClickHouse to retrieve order fulfillment metrics. Requires 'getMooseUtils' for client initialization.

```typescript
import {
  getMooseUtils
} from "@514labs/moose-lib";
import {
  orderFulfillmentModel
} from "../query-models/orderFulfillment.model";

interface OrderFulfillmentRequest {
  merchantId?: string;
  startDate?: string;
  endDate?: string;
  limit?: number;
  offset?: number;
  orderBy?: "merchantName" | "day" | "totalOrders" | "fulfillmentRate";
}

export async function getOrderFulfillment(request: OrderFulfillmentRequest) {
  const { client } = await getMooseUtils();

  return await orderFulfillmentModel.query(
    {
      dimensions: ["merchantName", "day"],
      metrics: ["totalOrders", "fulfilledOrders", "fulfillmentRate"],
      filters: {
        ...(request.merchantId && { merchantId: { eq: request.merchantId } }),
        ...(request.startDate && { day: { gte: request.startDate } }),
        ...(request.endDate && { day: { lte: request.endDate } }),
      },
      sortBy: request.orderBy ?? "merchantName",
      sortDir: "ASC",
      limit: request.limit ?? 100,
      offset: request.offset ?? 0,
    },
    client.query,
  );
}
```

--------------------------------

### Define a Basic API Endpoint in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/apis/analytics-api.mdx

Define an API endpoint with query parameters and a result type. Ensure `SourceTable` is not null using `!`. The `client.query.execute` method is used to run the SQL query.

```typescript
```ts filename="ExampleApi.ts" copy
import { Api } from "@514labs/moose-lib";
import { SourcePipeline } from "path/to/SourcePipeline"; 

// Define the query parameters
interface QueryParams {
  filterField: string;
  maxResults: number;
}

// Model the query result type
interface ResultItem {
  id: number;
  name: string;
  value: number;
}


const SourceTable = SourcePipeline.table!; // Use `!` to assert that the table is not null
const cols = SourceTable.columns;

// Define the result type as an array of the result item type
export const exampleApi = new Api<QueryParams, ResultItem[]>("example_endpoint",  
    async ({ filterField, maxResults }: QueryParams, { client, sql }) => {
        const query = sql.statement`
        SELECT
          ${cols.id},
          ${cols.name},
          ${cols.value}
        FROM ${SourceTable}
        WHERE category = ${filterField}
        LIMIT ${maxResults}`;

        // Set the result type to the type of the each row in the result set
        const resultSet = await client.query.execute<ResultItem>(query);

        // Return the result set as an array of the result item type
        return await resultSet.json();
    });
```
```

