import { IngestPipeline } from "@514labs/moose-lib";

// Product interaction event data model
export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: string;
  properties: Record<string, any>;
}

// Ingestion pipeline for product events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["event_ts", "user_id", "product_id"]
  },
  stream: true,
  ingestApi: true,
});

// Export consumption APIs
export * as topProducts from "./apis/top-products";
export * as conversionFunnel from "./apis/conversion-funnel";
export * as hourlyActivity from "./apis/hourly-activity";

