import { Api } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../index";

export interface HourlyActivityParams {
  hours?: number;
}

export interface HourlyActivityResponse {
  hour: string;
  total_events: number;
  views: number;
  purchases: number;
  unique_users: number;
}

const ProductEventTable = ProductEventPipeline.table!;
const cols = ProductEventTable.columns;

export const hourlyActivityApi = new Api<HourlyActivityParams, HourlyActivityResponse[]>(
  "hourly-activity",
  async ({ hours = 24 }: HourlyActivityParams, { client, sql }) => {
    const query = sql.statement`
      SELECT
        toString(toStartOfHour(${cols.event_ts})) as hour,
        count(*) as total_events,
        countIf(${cols.event_type} = 'view') as views,
        countIf(${cols.event_type} = 'purchase') as purchases,
        uniq(${cols.user_id}) as unique_users
      FROM ${ProductEventTable}
      WHERE ${cols.event_ts} >= now() - interval ${hours} hour
      GROUP BY hour
      ORDER BY hour DESC
      LIMIT ${hours}
    `;

    const resultSet = await client.query.execute<HourlyActivityResponse>(query);
    return await resultSet.json();
  }
);

